/** Card kinds that live outside an agent run: raised by chat or detection, decided one at a time. */
export const STANDALONE_KINDS = ["iou_create", "iou_settle", "transaction_create", "balance_set", "recurring_edit", "own_transfer"];

/** Card ids an assistant answer shows in its moneo-proposal(s) blocks. */
export function answerCardIds(content: string | null | undefined): string[] {
  return [...(content ?? "").matchAll(/```moneo-proposals?\n([\s\S]*?)```/g)].flatMap(match => match[1].match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi) ?? []);
}

/** A bank transaction a card is about (a repayment, a flagged charge), shown under the card so it can be decided there. */
export type CardTransaction = { id: string; date: string; description: string; amountMinor: string; currency: string };
export type OpenProposal = { id: string; kind: string; title: string; detail: string; status: string; conflict_key?: string; accounts?: { id: string; name: string }[]; selected?: string | null; createsCash?: boolean;
  transactions?: CardTransaction[] };

export const cardTransactions = (evidence: unknown): CardTransaction[] => {
  const rows = (evidence as { transactions?: unknown } | null)?.transactions;
  return Array.isArray(rows) ? rows.filter((row): row is CardTransaction => typeof row?.id === "string" && typeof row?.amountMinor === "string").slice(0, 8) : [];
};

/** Every open standalone card, oldest first, as IouCard shows it; an expense card carries the accounts it can be paid from. */
export async function openStandaloneProposals(supabase: SupabaseClient, workspaceId: string): Promise<OpenProposal[]> {
  const { data, error } = await supabase.from("agent_proposals").select("id, kind, title, detail, status, conflict_key, payload, evidence").eq("workspace_id", workspaceId).is("run_id", null)
    .in("kind", STANDALONE_KINDS).in("status", ["proposed", "failed"]).order("created_at").limit(100);
  if (error) throw new Error(error.message);
  return Promise.all((data ?? []).map(async ({ payload, evidence, ...row }) => {
    const transactions = cardTransactions(evidence), proposal = transactions.length ? { ...row, transactions } : row;
    // Without options the card still accepts into the proposed account, so one unreadable payload does not hide the rest.
    return proposal.kind === "transaction_create" ? { ...proposal, ...await transactionAccountOptions(supabase, workspaceId, payload).catch(() => ({})) } : proposal;
  }));
}
"use client";

import { useEffect, useState } from "react";
import { useBusy } from "@/components/use-busy";
import Link from "next/link";
import { decideAgentProposals } from "@/app/ai/agents/actions";
import { loadIouProposal, type ChatProposal } from "@/app/ai/iou-actions";
import { displayFormat } from "@/lib/display-format";
import { TradeCard } from "@/components/trade-card";

type Proposal = Pick<ChatProposal, "id" | "title" | "detail" | "status"> & Partial<ChatProposal> & { conflict_key?: string };

/** A loan, repayment or expense waiting for a yes/no. Nothing is saved until Add is pressed. */
export function IouCard({ id, initial, locale = "en-GB", onAccount, onDecided }: { id: string; initial?: Proposal; locale?: string; onAccount?: (id: string, accountId: string | undefined) => void; onDecided?: (id: string, undone?: boolean) => void }) {
  const [proposal, setProposal] = useState<Proposal | null | undefined>(initial);
  const [account, setAccount] = useState<string>();
  const [error, setError] = useState<string>();
  const [pending, start] = useBusy();
  const [unavailable, setUnavailable] = useState(false);
  const [attempt, setAttempt] = useState(0);
  // A failed load used to hide the card until the page was reloaded; it now says so and can be retried.
  useEffect(() => { if (!initial) loadIouProposal(id).then(setProposal, () => setUnavailable(true)); }, [id, initial, attempt]);
  if (unavailable) return <p role="alert" className="my-3 text-sm text-danger">Could not load this card. <button type="button" onClick={() => { setUnavailable(false); setAttempt(count => count + 1); }} className="underline">Try again</button></p>;
  if (proposal === undefined) return <p className="my-3 text-sm text-muted-foreground" role="status">Loading…</p>;
  if (!proposal) return null;
  if (proposal.trade) return <TradeCard id={id} proposal={{ ...proposal, trade: proposal.trade }} locale={locale} onChange={setProposal} />;
  const { date, money } = displayFormat(locale);
  const transaction = proposal.kind === "transaction_create";
  const balance = proposal.kind === "balance_set";
  const recurring = proposal.kind === "recurring_edit";
  const own = proposal.kind === "own_transfer";
  const chosen = account ?? proposal.selected ?? "";
  // Stated cash with no cash account yet: accepting creates one, and the button says so.
  const createsCash = transaction && !chosen && !!proposal.createsCash;
  const needsChoice = transaction && !chosen && !createsCash;
  // Shows the decision at once (the action also re-renders the slow Home page) and puts the card back if saving fails.
  const decide = (decision: "accept" | "reject") => start(async () => {
    const before = proposal;
    setError(undefined);
    setProposal({ ...proposal, status: decision === "accept" ? "accepted" : "rejected" });
    onDecided?.(id);
    try {
      const [outcome] = await decideAgentProposals([id], decision, transaction && chosen ? chosen : undefined);
      if (outcome.error) { setProposal(before); setError(outcome.error); onDecided?.(id, true); }
      // Reload so an accepted card links to what it created.
      else if (decision === "accept") loadIouProposal(id).then(loaded => loaded && setProposal(loaded), () => {});
    } catch (cause) { setProposal(before); setError(cause instanceof Error ? cause.message : "Could not save"); onDecided?.(id, true); }
  });
  // Many cards can be open at once, so a screen reader's button list needs more than "Add". Recurring cards keep their own short names.
  const named = (verb: string) => recurring ? undefined : `${verb}: ${proposal.title}`;
  const open = proposal.status === "proposed" || proposal.status === "failed";
  const done = transaction ? <>Added. {proposal.result?.href && <Link href={proposal.result.href} className="underline">Open transaction</Link>}
    {proposal.result?.createdAccount && <> A Cash account was created; <Link href="/money/accounts" className="underline">set its balance</Link> to count it in net worth.</>}</>
    : balance ? <>Saved. <Link href="/money/accounts" className="underline">See it on Accounts</Link></>
    : recurring ? <>Saved. <Link href="/money/recurring" className="underline">See it on Recurring</Link></>
    : own ? <>Moved to transfers. {proposal.result?.href && <Link href={proposal.result.href} className="underline">Open transaction</Link>}</>
    : <>Added. <Link href="/money/wealth" className="underline">See it in Wealth</Link></>;
  return <section aria-label={transaction ? "Transaction proposal" : balance ? "Balance proposal" : recurring ? "Recurring proposal" : own ? "Own account proposal" : "Loan proposal"} className="my-3 rounded-xl border border-ai-border bg-ai-soft p-4">
    <p className="font-medium">{proposal.title}</p>
    {proposal.detail && <p className="mt-1 text-sm text-muted-foreground">{proposal.detail}</p>}
    {open && !!proposal.transactions?.length && <details className="mt-2 text-sm">
      <summary className="cursor-pointer text-muted-foreground hover:text-foreground">Show the {proposal.transactions.length === 1 ? "transaction" : `${proposal.transactions.length} transactions`}</summary>
      <ul className="mt-2 divide-y divide-border rounded-lg border border-border bg-background">{proposal.transactions.map(row => <li key={row.id}>
        <Link href={`/money/transactions?transaction=${row.id}`} className="flex items-baseline gap-3 px-3 py-2 hover:bg-muted">
          <span className="shrink-0 font-mono text-xs text-muted-foreground">{date(row.date)}</span><span className="min-w-0 flex-1 truncate">{row.description}</span>
          <span className="shrink-0 font-mono">{money(row.amountMinor, row.currency)}</span></Link></li>)}</ul>
    </details>}
    {error && <p role="alert" className="mt-2 text-sm text-danger">{error}</p>}
    {open ? <div className="mt-3 flex flex-wrap items-center gap-2">
      {transaction && proposal.accounts && <label className="flex w-full min-w-0 items-center gap-2 text-sm sm:w-auto"><span className="text-muted-foreground">From</span>
        <select value={chosen} onChange={event => { setAccount(event.target.value); onAccount?.(id, event.target.value || undefined); }} disabled={pending} className="min-h-9 w-full min-w-0 flex-1 truncate rounded-lg border border-border bg-background px-2 tex
          {!chosen && <option value="">{createsCash ? "New Cash account" : "Choose an account"}</option>}
          {proposal.accounts.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}
        </select></label>}
      <button type="button" aria-label={named(own ? "Yes, it’s mine" : balance ? "Save" : createsCash ? "Create Cash account and add" : "Add")} disabled={pending || needsChoice} onClick={() => decide("accept")} className="min-h-9 rounded-lg bg-primary px-4 t
      <button type="button" aria-label={named(own ? "Not mine" : "Dismiss")} disabled={pending} onClick={() => decide("reject")} className="min-h-9 rounded-lg border border-border px-4 text-sm hover:bg-muted disabled:opacity-50">{proposal.conflict_key?.startsW
    </div> : <p role="status" className="mt-2 text-sm">{proposal.status === "accepted" ? done : recurring ? "Dismissed. It won’t be suggested again." : "Dismissed. Nothing was changed."}</p>}
  </section>;
}
  if (error) throw new Error(error.message);
  return { proposalId: data.id as string, title };
}

/** What the card offers: accounts in the proposal's currency, with the proposed one selected. */
export async function transactionAccountOptions(supabase: SupabaseClient, workspaceId: string, payload: unknown) {
  const parsed = transactionCreateSchema.parse(payload);
  const accounts = await liveAccounts(supabase, workspaceId, parsed.currencyCode);
  // A Cash account may have appeared since this was proposed, for instance by accepting another stated-cash card.
  const cash = parsed.paidInCash ? accounts.find(account => account.type === "cash") : undefined;
  return { accounts: accounts.map(({ id, name }) => ({ id, name })), selected: parsed.accountId ?? cash?.id ?? null, createsCash: !!parsed.paidInCash && !cash };
}

/** Records the accepted proposal as an audited manual transaction; the proposal id is the request id, so accepting twice cannot duplicate it. */
export async function applyTransactionProposal({ supabase, workspace }: Context, proposalId: string, payload: unknown, accountOverride?: string) {
  const parsed = transactionCreateSchema.parse(payload);
  let accountId = accountOverride ?? parsed.accountId, createdAccount = false;
  if (!accountId) {
    if (!parsed.paidInCash) throw new Error("Choose an account for this transaction");
    const cash = (await liveAccounts(supabase, workspace.id, parsed.currencyCode)).find(account => account.type === "cash");
    if (cash) accountId = cash.id;
    else {
      const created = await supabase.from("accounts").insert({ workspace_id: workspace.id, name: "Cash", type: "cash", currency_code: parsed.currencyCode }).select("id").single();
      if (created.error) throw new Error(created.error.message);
      accountId = created.data.id as string; createdAccount = true;
    }
  }
  const account = await supabase.from("accounts").select("currency_code").eq("workspace_id", workspace.id).eq("id", accountId).is("archived_at", null).maybeSingle();
  if (account.error || !account.data) throw new Error("Account not found");
  if (account.data.currency_code !== parsed.currencyCode) throw new Error(`Choose an account in ${parsed.currencyCode}`);
  const { data, error } = await supabase.rpc("create_manual_transaction", { p_account_id: accountId, p_posted_on: parsed.date, p_description: parsed.description,
    p_amount_minor: parsed.direction === "spent" ? `-${parsed.amountMinor}` : parsed.amountMinor, p_status: "posted", p_category_id: parsed.categoryId,
    p_note: "Added from chat", p_request_id: proposalId });
  if (error) throw new Error(error.message);
  return { href: `/money/transactions?transaction=${data.id}`, undo: "Undo from the transaction", accountId, createdAccount };
}
