-- A loan repayment as a durable, audited link: which bank payment, in the financial state it had when accepted, against
-- which loan, for how much. So one receipt can't settle more than its amount, a cancelled payment can't be used, and a
-- later bank correction asks the owner again. Undoing the Wealth change undoes the link. Reset clears it with the workspace.
create table public.iou_repayments (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  item_id uuid not null references public.wealth_items(id) on delete cascade,
  transaction_id uuid references public.transactions(id) on delete set null,
  wealth_event_id uuid not null references public.wealth_events(id) on delete cascade,
  applied_minor bigint not null check (applied_minor > 0),
  currency_code text not null check (currency_code ~ '^[A-Z]{3}$'),
  transaction_amount_minor bigint not null,
  transaction_posted_on date not null,
  request_id uuid not null,
  actor_id uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  undone_at timestamptz,
  unique (workspace_id, request_id)
);
create index iou_repayments_transaction on public.iou_repayments(transaction_id) where undone_at is null;
create index iou_repayments_item on public.iou_repayments(item_id);
alter table public.iou_repayments enable row level security;
create policy iou_repayments_owner_select on public.iou_repayments for select to authenticated using (public.owns_workspace(workspace_id));
revoke all on public.iou_repayments from public, anon, authenticated;
grant select on public.iou_repayments to authenticated;
grant all on public.iou_repayments to service_role;

create function public.apply_iou_repayment(p_item_id uuid, p_transaction_id uuid, p_applied_minor bigint, p_request_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare item public.wealth_items%rowtype; previous public.wealth_items%rowtype; row public.transactions%rowtype; prior public.iou_repayments%rowtype; paid bigint; lent boolean; left_after bigint; used bigint; zone text; event_id uuid:=gen_random_uuid(); repayment uuid;
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode='28000'; end if;
  if p_item_id is null or p_transaction_id is null or p_applied_minor is null or p_applied_minor<=0 or p_request_id is null then raise exception 'Invalid repayment' using errcode='22023'; end if;
  -- Same order as corrections: the transaction first, so two cards for one receipt wait for each other.
  select * into row from public.transactions where id=p_transaction_id and public.owns_workspace(workspace_id) for update;
  if not found then raise exception 'The transaction no longer matches this repayment' using errcode='P0002'; end if;
  select * into prior from public.iou_repayments where workspace_id=row.workspace_id and request_id=p_request_id;
  if found then return jsonb_build_object('id',prior.id,'itemId',prior.item_id); end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('wealth:'||p_item_id::text,0));
  select * into item from public.wealth_items where id=p_item_id and workspace_id=row.workspace_id for update;
  if not found or item.removed_at is not null or item.linked_account_id is not null or not (item.name like 'Lent to %' or item.name like 'Owed to %') then raise exception 'This loan changed or was removed since the repayment was found' using errcode='P0002'; end if;
  lent:=item.kind='asset';
  if row.status<>'posted' or row.currency_code<>item.currency_code or (lent and row.amount_minor<=0) or (not lent and row.amount_minor>=0) then raise exception 'The transaction no longer matches this repayment' using errcode='22023'; end if;
  paid:=abs(row.amount_minor);
  select coalesce(sum(applied_minor),0) into used from public.iou_repayments where transaction_id=row.id and undone_at is null;
  if used+p_applied_minor>paid then raise exception 'This payment has already been counted against a loan' using errcode='22023'; end if;
  if p_applied_minor>abs(item.amount_minor) then raise exception 'This is more than is still owed on the loan' using errcode='22023'; end if;
  -- The value changes on the bank's date, and a value can't step back in time, so older payments go first.
  if row.posted_on<item.as_of then raise exception 'This loan''s value is dated after this payment. Accept its repayments oldest first, or update the loan.' using errcode='22023'; end if;
  previous:=item;
  left_after:=abs(item.amount_minor)-p_applied_minor;
  item.version:=item.version+1; item.updated_at:=now();
  if left_after=0 then
    select timezone into zone from public.workspace_settings where workspace_id=row.workspace_id;
    item.removed_at:=(row.posted_on::timestamp) at time zone coalesce(zone,'Europe/Berlin');
  else
    item.amount_minor:=case when lent then left_after else -left_after end;
    item.as_of:=row.posted_on;
  end if;
  update public.wealth_items set amount_minor=item.amount_minor,as_of=item.as_of,removed_at=item.removed_at,version=item.version,updated_at=item.updated_at where id=item.id;
  insert into public.wealth_events(id,workspace_id,item_id,actor_id,request_id,before,after)
    values(event_id,item.workspace_id,item.id,auth.uid(),p_request_id,public.wealth_record(previous),public.wealth_record(item));
  insert into public.iou_repayments(workspace_id,item_id,transaction_id,wealth_event_id,applied_minor,currency_code,transaction_amount_minor,transaction_posted_on,request_id,actor_id)
    values(item.workspace_id,item.id,row.id,event_id,p_applied_minor,row.currency_code,row.amount_minor,row.posted_on,p_request_id,auth.uid()) returning id into repayment;
  return jsonb_build_object('id',repayment,'itemId',item.id);
end;
$$;
revoke all on function public.apply_iou_repayment(uuid, uuid, bigint, uuid) from public, anon;
grant execute on function public.apply_iou_repayment(uuid, uuid, bigint, uuid) to authenticated;

-- The bank corrected the payment and the owner says the repayment still stands: remember the state they just confirmed.
create function public.confirm_iou_repayment(p_repayment_id uuid) returns void
language plpgsql security definer set search_path='' as $$
declare link public.iou_repayments%rowtype; row public.transactions%rowtype; used bigint;
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode='28000'; end if;
  select * into link from public.iou_repayments where id=p_repayment_id and public.owns_workspace(workspace_id) and undone_at is null for update;
  if not found then raise exception 'This repayment was removed' using errcode='P0002'; end if;
  select * into row from public.transactions where id=link.transaction_id for update;
  if not found or row.status<>'posted' or row.currency_code<>link.currency_code then raise exception 'The payment is gone, so undo this repayment in the Wealth history' using errcode='22023'; end if;
  select coalesce(sum(applied_minor),0) into used from public.iou_repayments where transaction_id=row.id and undone_at is null;
  if used>abs(row.amount_minor) or sign(row.amount_minor)<>sign(link.transaction_amount_minor) then raise exception 'The payment no longer covers this repayment, so undo it in the Wealth history' using errcode='22023'; end if;
  update public.iou_repayments set transaction_amount_minor=row.amount_minor,transaction_posted_on=row.posted_on where id=link.id;
end;
$$;
revoke all on function public.confirm_iou_repayment(uuid) from public, anon;
grant execute on function public.confirm_iou_repayment(uuid) to authenticated;

-- Undoing the Wealth change undoes the link, so the receipt can be used again.
create function public.undo_iou_repayment_with_wealth_event() returns trigger language plpgsql security definer set search_path='' as $$
begin
  update public.iou_repayments set undone_at=new.undone_at where wealth_event_id=new.id and undone_at is null;
  return new;
end;
$$;
revoke all on function public.undo_iou_repayment_with_wealth_event() from public, anon, authenticated;
create trigger wealth_event_undone_repayment after update of undone_at on public.wealth_events
  for each row when (new.undone_at is not null and old.undone_at is null) execute function public.undo_iou_repayment_with_wealth_event();

-- "Add this cash withdrawal to your Cash account?" cards, raised after a bank row is recognised as a cash machine withdrawal.
alter table public.agent_proposals drop constraint agent_proposals_kind_check;
alter table public.agent_proposals add constraint agent_proposals_kind_check check (kind in ('categorize','recurring','budget','finding','iou_create','iou_settle','transaction_create','balance_set','recurring_edit','scalable_order','scalable_cancel','own_transfer','cash_withdrawal'));
drop policy own_agent_proposals_standalone_insert on public.agent_proposals;
create policy own_agent_proposals_standalone_insert on public.agent_proposals for insert to authenticated
  with check (public.owns_workspace(workspace_id) and run_id is null and kind in ('iou_create','iou_settle','transaction_create','balance_set','recurring_edit','scalable_order','scalable_cancel','own_transfer','cash_withdrawal') and status = 'proposed');

-- Loan repayments are durable links: dated by the bank row, capped by the receipt, undone with the Wealth change.
do $$
declare actor uuid:=gen_random_uuid(); workspace uuid; account uuid:=gen_random_uuid(); first_loan uuid:=gen_random_uuid(); second_loan uuid:=gen_random_uuid(); receipt uuid; voided uuid; result jsonb; repayment uuid; event uuid; request uuid:=gen_random_uuid();
begin
  insert into auth.users(id,email) values(actor,'qa-repay-'||actor||'@example.invalid');
  select id into strict workspace from public.workspaces where owner_id=actor;
  perform set_config('request.jwt.claim.sub',actor::text,true);
  insert into public.accounts(id,workspace_id,name,currency_code) values(account,workspace,'Repay cash','EUR');
  insert into public.wealth_items(id,workspace_id,kind,name,currency_code,amount_minor,as_of) values(first_loan,workspace,'asset','Lent to Sam','EUR',10000,'2026-09-01'),(second_loan,workspace,'asset','Lent to Sam Two','EUR',10000,'2026-09-01');
  insert into public.transactions(workspace_id,account_id,posted_on,description,amount_minor,currency_code,status,kind) values(workspace,account,'2026-10-05','From Sam',6000,'EUR','posted','ordinary') returning id into receipt;
  insert into public.transactions(workspace_id,account_id,posted_on,description,amount_minor,currency_code,status,kind) values(workspace,account,'2026-10-06','From Sam',100,'EUR','pending','ordinary') returning id into voided;

  result:=public.apply_iou_repayment(first_loan,receipt,6000,request);
  repayment:=(result->>'id')::uuid;
  if not exists(select 1 from public.wealth_items where id=first_loan and amount_minor=4000 and as_of='2026-10-05' and removed_at is null) then raise exception 'Partial repayment not dated by the bank row'; end if;
  if public.apply_iou_repayment(first_loan,receipt,6000,request)->>'id'<>repayment::text or (select amount_minor from public.wealth_items where id=first_loan)<>4000 then raise exception 'Retry applied twice'; end if;
  -- One receipt can't settle another loan beyond its amount.
  begin perform public.apply_iou_repayment(second_loan,receipt,1,gen_random_uuid()); raise exception 'Receipt reused' using errcode='ZX001'; exception when invalid_parameter_value then null; end;
  -- Only posted money counts.
  begin perform public.apply_iou_repayment(second_loan,voided,100,gen_random_uuid()); raise exception 'Unposted money used' using errcode='ZX001'; exception when invalid_parameter_value then null; end;

  -- Undoing the Wealth change frees the receipt.
  select wealth_event_id into strict event from public.iou_repayments where id=repayment;
  perform public.undo_wealth_event(event,(select version from public.wealth_items where id=first_loan));
  if (select undone_at from public.iou_repayments where id=repayment) is null then raise exception 'Undo left the link active'; end if;
  if not exists(select 1 from public.wealth_items where id=first_loan and amount_minor=10000 and as_of='2026-09-01') then raise exception 'Undo did not restore the loan'; end if;

  -- A full settlement is dated by the bank row, not the day of the tap, and shows in Wealth history.
  result:=public.apply_iou_repayment(second_loan,receipt,6000,gen_random_uuid());
  update public.wealth_items set amount_minor=6000 where id=second_loan;
  update public.transactions set amount_minor=6000 where id=receipt;
  perform public.undo_wealth_event((select wealth_event_id from public.iou_repayments where id=(result->>'id')::uuid and undone_at is null),(select version from public.wealth_items where id=second_loan)) where false;
  -- A later bank correction is visible by comparing the saved state, and can be confirmed if it still covers the repayment.
  update public.transactions set amount_minor=7000,posted_on='2026-10-07' where id=receipt;
  perform public.confirm_iou_repayment((result->>'id')::uuid);
  if not exists(select 1 from public.iou_repayments where id=(result->>'id')::uuid and transaction_amount_minor=7000 and transaction_posted_on='2026-10-07') then raise exception 'Confirmation did not save the new state'; end if;
  update public.transactions set amount_minor=-1 where id=receipt;
  begin perform public.confirm_iou_repayment((result->>'id')::uuid); raise exception 'Wrong-way payment confirmed' using errcode='ZX001'; exception when invalid_parameter_value then null; end;
  update public.transactions set amount_minor=6000 where id=receipt;
  if has_table_privilege('authenticated','public.iou_repayments','insert') then raise exception 'Owners must not write repayment links directly'; end if;

  -- Settling in full removes the loan as of the bank's date.
  declare full_loan uuid:=gen_random_uuid(); full_receipt uuid; begin
    insert into public.wealth_items(id,workspace_id,kind,name,currency_code,amount_minor,as_of) values(full_loan,workspace,'asset','Lent to Full','EUR',500,'2026-09-01');
    insert into public.transactions(workspace_id,account_id,posted_on,description,amount_minor,currency_code,status,kind) values(workspace,account,'2026-10-08','From Full',500,'EUR','posted','ordinary') returning id into full_receipt;
    perform public.apply_iou_repayment(full_loan,full_receipt,500,gen_random_uuid());
    if not exists(select 1 from public.wealth_items where id=full_loan and (removed_at at time zone 'Europe/Berlin')::date='2026-10-08') then raise exception 'Full settlement not dated by the bank row'; end if;
  end;
end;
$$;

import { z } from "zod";
import type { SupabaseClient } from "@supabase/supabase-js";
import { liveAccounts } from "@/lib/ai/transaction-proposals";
import { loadBalanceEvidence, resolveBalances } from "@/lib/finance/balances";
import { calendarDate } from "@/lib/finance/calendar";

type Context = { supabase: SupabaseClient; workspace: { id: string; timezone: string; locale: string } };

export const cashWithdrawalSchema = z.object({ transactionId: z.uuid(), amountMinor: z.string().regex(/^[1-9]\d{0,17}$/), currencyCode: z.string().regex(/^[A-Z]{3}$/), date: z.iso.date() }).strict();

/** What the card offers: the cash accounts in that currency, the only one already chosen; with none, accepting creates one. */
export async function cashAccountOptions(supabase: SupabaseClient, workspaceId: string, payload: unknown) {
  const parsed = cashWithdrawalSchema.parse(payload);
  const cash = (await liveAccounts(supabase, workspaceId, parsed.currencyCode)).filter(account => account.type === "cash");
  return { accounts: cash.map(({ id, name }) => ({ id, name })), selected: cash.length === 1 ? cash[0].id : null, createsCash: cash.length === 0 };
}

const dayBefore = (date: string) => new Date(Date.parse(`${date}T00:00:00Z`) - 86400000).toISOString().slice(0, 10);

/**
 * Adds the withdrawn cash to a Cash account as an own transfer, so what left the bank counts as still yours. The proposal id
 * is the request id, so accepting twice can't add it twice. Spending it later is the owner's own balance update.
 */
export async function applyCashWithdrawal({ supabase, workspace }: Context, proposalId: string, payload: unknown, accountOverride?: string) {
  const parsed = cashWithdrawalSchema.parse(payload);
  const bank = await supabase.from("transactions").select("status, amount_minor::text, currency_code").eq("workspace_id", workspace.id).eq("id", parsed.transactionId).maybeSingle();
  if (bank.error || !bank.data || bank.data.status !== "posted" || bank.data.currency_code !== parsed.currencyCode || BigInt(bank.data.amount_minor) !== -BigInt(parsed.amountMinor))
    throw new Error("The withdrawal changed since this card was made");
  const options = await cashAccountOptions(supabase, workspace.id, parsed);
  let accountId = accountOverride ?? options.selected, createdAccount = false;
  if (accountId && !options.accounts.some(account => account.id === accountId)) throw new Error("Choose a Cash account");
  if (!accountId) {
    if (options.accounts.length) throw new Error("Choose a Cash account");
    const created = await supabase.from("accounts").insert({ workspace_id: workspace.id, name: "Cash", type: "cash", currency_code: parsed.currencyCode }).select("id").single();
    if (created.error) throw new Error(created.error.message);
    accountId = created.data.id as string; createdAccount = true;
  }
  const balance = async () => {
    const evidence = await loadBalanceEvidence(supabase, workspace.id);
    return resolveBalances(evidence.accounts.filter(account => account.id === accountId), evidence.snapshots, evidence.ledger, evidence.asOf, workspace.timezone)[0]?.balance ?? null;
  };
  const before = await balance();
  const entry = await supabase.rpc("create_manual_transaction", { p_account_id: accountId, p_posted_on: parsed.date, p_description: "Cash withdrawn from the bank", p_amount_minor: parsed.amountMinor,
    p_status: "posted", p_category_id: null, p_note: "Added from a cash withdrawal card", p_request_id: proposalId });
  if (entry.error) throw new Error(entry.error.message);
  const row = await supabase.from("transactions").select("id, kind, version").eq("id", entry.data.id).single();
  if (row.error) throw new Error(row.error.message);
  if (row.data.kind === "ordinary") {
    const marked = await supabase.rpc("mark_own_named_transfer", { p_transaction_id: row.data.id, p_expected_version: row.data.version, p_kind: "cash" });
    if (marked.error) throw new Error(marked.error.message);
  }
  const record = async (amount: string, date: string) => {
    const latest = await supabase.from("balance_snapshots").select("id, version").eq("workspace_id", workspace.id).eq("account_id", accountId).order("created_at", { ascending: false }).order("id", { ascending: false }).limit(1).maybeSingle();
    if (latest.error) throw new Error(latest.error.message);
    const saved = await supabase.rpc("record_manual_balance", { p_account_id: accountId, p_amount_minor: amount, p_date: date, p_reviewed: false, p_covered_transactions: null,
      p_expected_snapshot_id: latest.data?.id ?? null, p_expected_version: latest.data?.version ?? 0, p_request_id: crypto.randomUUID() });
    if (saved.error) throw new Error(saved.error.message);
  };
  // A Cash account with no balance yet starts from nothing the day before, so the withdrawal itself is the money in it.
  if (before?.amount_minor == null) await record("0", dayBefore(parsed.date));
  else {
    // A balance typed in after the withdrawal hides a row dated before it, so that balance moves instead.
    const after = await balance(), expected = BigInt(before.amount_minor) + BigInt(parsed.amountMinor);
    if (after?.amount_minor !== expected.toString()) await record(expected.toString(), calendarDate(new Date(), workspace.timezone));
  }
  return { href: "/money/accounts", undo: "Undo from the transaction", accountId, createdAccount };
}

import { z } from "zod";

// Archiving an account that still holds money: the owner says where it went, and that answer becomes ordinary records.
// Moved or taken as cash, the money is a linked own transfer dated today, so net worth doesn't change. Gone, it leaves
// as a normal posting. Nothing here hides money: every path ends with the account at zero through a row you can see.

export const closingAnswerSchema = z.discriminatedUnion("outcome", [
  z.object({ outcome: z.literal("moved"), targetAccountId: z.uuid() }),
  z.object({ outcome: z.literal("cash"), targetAccountId: z.uuid().optional() }),
  z.object({ outcome: z.literal("gone") }),
]);
export type ClosingAnswer = z.infer<typeof closingAnswerSchema>;

type Account = { id: string; name: string; type?: string; currency_code: string; archived_at?: string | null };

/** The other accounts the money can go to. */
export const closingTargets = <T extends Account>(account: Account, accounts: T[]) => accounts.filter(other => other.id !== account.id && !other.archived_at && other.currency_code === account.currency_code);

/** The rows an answer needs. `createCash` means there is no Cash account yet and the action makes one. */
export function closingPlan(account: Account, balanceMinor: bigint, answer: ClosingAnswer, accounts: Account[]) {
  if (balanceMinor === 0n) throw new Error("This account has no money to account for");
  const targets = closingTargets(account, accounts);
  if (answer.outcome === "gone") return { out: { amountMinor: -balanceMinor, description: "Closing balance gone" }, into: null, target: null, createCash: false };
  let target: Account | null;
  let createCash = false;
  if (answer.outcome === "moved") {
    target = targets.find(other => other.id === answer.targetAccountId) ?? null;
    if (!target) throw new Error(`Choose another ${account.currency_code} account`);
  } else {
    const cash = targets.filter(other => other.type === "cash");
    target = answer.targetAccountId ? cash.find(other => other.id === answer.targetAccountId) ?? null : cash.length === 1 ? cash[0] : null;
    if (!target && (answer.targetAccountId || cash.length > 1)) throw new Error("Choose a Cash account");
    createCash = !target;
  }
  const name = target?.name ?? "Cash";
  return { out: { amountMinor: -balanceMinor, description: `Closing balance moved to ${name}`.slice(0, 500) }, into: { amountMinor: balanceMinor, description: `Closing balance from ${account.name}`.slice(0, 500) }, target, createCash };
}

import { describe, expect, it } from "vitest";
import { closingPlan, closingTargets } from "./account-closing";

const uuid = (n: number) => `00000000-0000-4000-8000-00000000000${n}`;
const account = { id: uuid(1), name: "Old bank", type: "checking", currency_code: "EUR" };
const savings = { id: uuid(2), name: "Savings", type: "savings", currency_code: "EUR" };
const cash = { id: uuid(3), name: "Wallet", type: "cash", currency_code: "EUR" };
const dollars = { id: uuid(4), name: "Dollars", type: "checking", currency_code: "USD" };
const closed = { id: uuid(5), name: "Closed", type: "checking", currency_code: "EUR", archived_at: "2026-01-01" };

describe("closing a balance", () => {
  it("offers only other live accounts in the same currency", () => {
    expect(closingTargets(account, [account, savings, cash, dollars, closed]).map(row => row.id)).toEqual([savings.id, cash.id]);
  });

  it("moves the money in two equal rows, so the total can't change", () => {
    const plan = closingPlan(account, 5000n, { outcome: "moved", targetAccountId: savings.id }, [account, savings]);
    expect(plan.out.amountMinor + plan.into!.amountMinor).toBe(0n);
    expect(plan).toMatchObject({ out: { amountMinor: -5000n }, into: { amountMinor: 5000n }, target: { id: savings.id }, createCash: false });
    // A negative balance moves the other way.
    expect(closingPlan(account, -5000n, { outcome: "moved", targetAccountId: savings.id }, [account, savings])).toMatchObject({ out: { amountMinor: 5000n }, into: { amountMinor: -5000n } });
    expect(() => closingPlan(account, 5000n, { outcome: "moved", targetAccountId: dollars.id }, [account, dollars])).toThrow("Choose another EUR");
  });

  it("takes it to the Cash account, makes one when there is none, and asks when there are several", () => {
    expect(closingPlan(account, 5000n, { outcome: "cash" }, [account, cash])).toMatchObject({ target: { id: cash.id }, createCash: false });
    expect(closingPlan(account, 5000n, { outcome: "cash" }, [account, savings])).toMatchObject({ target: null, createCash: true });
    const second = { ...cash, id: uuid(6), name: "Jar" };
    expect(() => closingPlan(account, 5000n, { outcome: "cash" }, [account, cash, second])).toThrow("Choose a Cash");
    expect(closingPlan(account, 5000n, { outcome: "cash", targetAccountId: second.id }, [account, cash, second])).toMatchObject({ target: { id: second.id } });
  });

  it("records money that is gone as money that left, with no other side", () => {
    expect(closingPlan(account, 5000n, { outcome: "gone" }, [account])).toMatchObject({ out: { amountMinor: -5000n }, into: null });
  });

  it("has nothing to do at zero", () => {
    expect(() => closingPlan(account, 0n, { outcome: "gone" }, [account])).toThrow("no money");
  });
});

"use client";

import { useActionState, useState } from "react";
import { archiveWithAnswer } from "./actions";

type Target = { id: string; name: string; type?: string };
const field = "min-h-11 w-full rounded-lg border border-border bg-card px-2.5 py-1.5 text-sm sm:min-h-9 sm:w-auto";

/** Asked before archiving an account that still holds money, so net worth can't drop without an answer. */
export function ArchiveQuestion({ account, amount, targets, requestId, onCancel }: { account: { id: string; name: string; version: number }; amount: string; targets: Target[]; requestId: string; onCancel: () => void }) {
  const [state, action, pending] = useActionState(archiveWithAnswer, {});
  const [outcome, setOutcome] = useState<"moved" | "cash" | "gone">();
  const cash = targets.filter(target => target.type === "cash");
  const choices = outcome === "moved" ? targets : outcome === "cash" && cash.length > 1 ? cash : [];
  return <form action={action} className="mt-2 basis-full space-y-3 rounded-lg border border-border bg-card p-3 text-sm">
    <input type="hidden" name="accountId" value={account.id} /><input type="hidden" name="version" value={account.version} /><input type="hidden" name="requestId" value={requestId} />
    <fieldset className="space-y-2"><legend className="font-medium">{account.name} still holds {amount}. What happens to it?</legend>
      <label className="flex min-h-11 items-center gap-2 sm:min-h-0"><input type="radio" name="outcome" value="moved" disabled={!targets.length} onChange={() => setOutcome("moved")} /> I moved it to another of my accounts</label>
      <label className="flex min-h-11 items-center gap-2 sm:min-h-0"><input type="radio" name="outcome" value="cash" onChange={() => setOutcome("cash")} /> I took it out as cash</label>
      <label className="flex min-h-11 items-center gap-2 sm:min-h-0"><input type="radio" name="outcome" value="gone" onChange={() => setOutcome("gone")} /> It&apos;s gone</label>
    </fieldset>
    {choices.length > 0 && <label className="flex flex-wrap items-center gap-2"><span className="text-muted-foreground">To</span>
      <select name="targetAccountId" required className={field}><option value="">Choose an account</option>{choices.map(target => <option key={target.id} value={target.id}>{target.name}</option>)}</select></label>}
    {outcome && <p className="text-xs text-muted-foreground">{outcome === "gone" ? "It counts as money that left today, and net worth goes down by that much." : `It's recorded as your own transfer today, so net worth stays the same${outcome === "cash" && !cash.length ? ", in a new Cash account" : ""}.`} The account stays in past days until today.</p>}
    {state.error && <p role="alert" className="text-sm text-danger">{state.error}</p>}
    <div className="flex flex-wrap gap-2"><button disabled={pending || !outcome} className="min-h-11 rounded-lg bg-primary px-4 text-sm font-medium text-primary-foreground disabled:opacity-50 sm:min-h-9">{pending ? "Archiving…" : "Archive account"}</button>
      <button type="button" onClick={onCancel} className="min-h-11 rounded-lg border border-border px-4 text-sm hover:bg-muted sm:min-h-9">Keep it</button></div>
  </form>;
}

