-- Money Scalable itself says moved in or out of the broker, once per transfer by Scalable's own ID. A returned withdrawal
-- is linked to its return (RETURN-<withdrawal id>), and neither is ever deleted: read-time rules decide how charts show them.
-- A disconnect keeps these rows, as it keeps synced values; reset clears them with the workspace.
create table public.scalable_transfers (
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  provider_id text not null check (char_length(provider_id) between 1 and 200),
  type text not null check (type in ('DEPOSIT','WITHDRAWAL')),
  amount_minor bigint not null check (amount_minor <> 0),
  currency_code text not null check (currency_code ~ '^[A-Z]{3}$'),
  occurred_at timestamptz not null,
  on_date date not null,
  status text not null check (char_length(status) between 1 and 40),
  is_cancellation boolean not null default false,
  description text check (char_length(description) <= 500),
  returns_provider_id text check (char_length(returns_provider_id) <= 200),
  revision integer not null default 1,
  revisions jsonb not null default '[]' check (jsonb_typeof(revisions) = 'array'),
  first_seen_at timestamptz not null default now(),
  primary key (workspace_id, provider_id)
);
create index scalable_transfers_date on public.scalable_transfers(workspace_id, on_date);
alter table public.scalable_transfers enable row level security;
create policy scalable_transfers_owner_select on public.scalable_transfers for select to authenticated using (public.owns_workspace(workspace_id));
revoke all on public.scalable_transfers from public, anon, authenticated;
grant select on public.scalable_transfers to authenticated;
grant all on public.scalable_transfers to service_role;

-- When the whole list was read. Until then recent syncs may hold only part of the history, so a bank row without a broker side isn't called unresolved.
alter table public.scalable_connections add column transfers_backfilled_at timestamptz;
grant select (transfers_backfilled_at) on public.scalable_connections to authenticated;

create function public.save_scalable_transfers(p_connection_id uuid, p_rows jsonb, p_complete boolean) returns integer
language plpgsql security definer set search_path='' as $$
declare connection public.scalable_connections%rowtype; entry jsonb; prior public.scalable_transfers%rowtype; changed integer := 0;
begin
  if p_connection_id is null or p_complete is null or jsonb_typeof(p_rows) is distinct from 'array' then raise exception 'Invalid Scalable transfers' using errcode = '22023'; end if;
  select * into connection from public.scalable_connections where id = p_connection_id and status = 'active' for update;
  if not found then raise exception 'Scalable connection is not active' using errcode = 'P0002'; end if;
  for entry in select value from jsonb_array_elements(p_rows) loop
    select * into prior from public.scalable_transfers where workspace_id = connection.workspace_id and provider_id = entry->>'provider_id' for update;
    if not found then
      insert into public.scalable_transfers(workspace_id, provider_id, type, amount_minor, currency_code, occurred_at, on_date, status, is_cancellation, description, returns_provider_id)
        values (connection.workspace_id, entry->>'provider_id', entry->>'type', (entry->>'amount_minor')::bigint, entry->>'currency_code', (entry->>'occurred_at')::timestamptz, (entry->>'on_date')::date,
          entry->>'status', coalesce((entry->>'is_cancellation')::boolean, false), entry->>'description', entry->>'returns_provider_id');
      changed := changed + 1;
    elsif (prior.type, prior.amount_minor, prior.currency_code, prior.occurred_at, prior.on_date, prior.status, prior.is_cancellation, prior.description) is distinct from
      (entry->>'type', (entry->>'amount_minor')::bigint, entry->>'currency_code', (entry->>'occurred_at')::timestamptz, (entry->>'on_date')::date, entry->>'status', coalesce((entry->>'is_cancellation')::boolean, false), entry->>'description') then
      -- Scalable revised it: the earlier state stays on the row.
      update public.scalable_transfers set type = entry->>'type', amount_minor = (entry->>'amount_minor')::bigint, currency_code = entry->>'currency_code', occurred_at = (entry->>'occurred_at')::timestamptz,
        on_date = (entry->>'on_date')::date, status = entry->>'status', is_cancellation = coalesce((entry->>'is_cancellation')::boolean, false), description = entry->>'description', revision = prior.revision + 1,
        revisions = prior.revisions || jsonb_build_array(to_jsonb(prior) - array['workspace_id','revisions','first_seen_at'])
        where workspace_id = connection.workspace_id and provider_id = prior.provider_id;
      changed := changed + 1;
    end if;
  end loop;
  if p_complete then update public.scalable_connections set transfers_backfilled_at = now() where id = connection.id; end if;
  return changed;
end;
$$;
revoke all on function public.save_scalable_transfers(uuid, jsonb, boolean) from public, anon, authenticated;
grant execute on function public.save_scalable_transfers(uuid, jsonb, boolean) to service_role;

-- Scalable's transfers are saved once by its own ID, keep earlier states, and only an active connection can write them.
do $$
declare actor uuid:=gen_random_uuid(); workspace uuid; connection uuid:=gen_random_uuid(); row_one jsonb; saved public.scalable_transfers%rowtype;
begin
  insert into auth.users(id,email) values(actor,'qa-transfers-'||actor||'@example.invalid');
  select id into strict workspace from public.workspaces where owner_id=actor;
  insert into public.scalable_connections(id,workspace_id,client_id,redirect_uri,status,tokens_encrypted) values(connection,workspace,'client','http://localhost/callback','active','one');
  row_one:=jsonb_build_object('provider_id','W1','type','WITHDRAWAL','amount_minor','-40000','currency_code','EUR','occurred_at','2026-08-24T09:00:00Z','on_date','2026-08-24','status','PENDING','is_cancellation',false,'description','Withdrawal','returns_provider_id',null);
  if public.save_scalable_transfers(connection,jsonb_build_array(row_one,row_one||'{"provider_id":"RETURN-W1","type":"DEPOSIT","amount_minor":"40000","returns_provider_id":"W1"}'),false)<>2 then raise exception 'Expected two new transfers'; end if;
  if public.save_scalable_transfers(connection,jsonb_build_array(row_one),false)<>0 then raise exception 'The same transfer counted as new'; end if;
  if public.save_scalable_transfers(connection,jsonb_build_array(row_one||'{"status":"SETTLED"}'),true)<>1 then raise exception 'A revision was not saved'; end if;
  select * into strict saved from public.scalable_transfers where workspace_id=workspace and provider_id='W1';
  if saved.status<>'SETTLED' or saved.revision<>2 or saved.revisions->0->>'status'<>'PENDING' then raise exception 'The earlier state was lost'; end if;
  if (select returns_provider_id from public.scalable_transfers where workspace_id=workspace and provider_id='RETURN-W1')<>'W1' then raise exception 'The return lost its withdrawal'; end if;
  if (select transfers_backfilled_at from public.scalable_connections where id=connection) is null then raise exception 'A complete read was not remembered'; end if;
  if has_function_privilege('authenticated','public.save_scalable_transfers(uuid,jsonb,boolean)','execute') then raise exception 'Owners must not write broker records'; end if;
  update public.scalable_connections set status='revoked',tokens_encrypted=null where id=connection;
  begin perform public.save_scalable_transfers(connection,'[]',false); raise exception 'A disconnected connection wrote transfers' using errcode='ZX001'; exception when sqlstate 'P0002' then null; end;
  if not exists(select 1 from public.scalable_transfers where workspace_id=workspace) then raise exception 'Disconnecting must keep the records'; end if;
end;
$$;

import { z } from "zod";
import { serviceDb } from "@/lib/bank/server";
import { calendarDate } from "@/lib/finance/calendar";
import type { ScalableMcp } from "./client";
import { toMinor } from "./live";
import { withScalable } from "./server";

// Scalable's own record of money moving in or out of the broker. It lists these as cash rows of type DEPOSIT or WITHDRAWAL;
// a withdrawal that bounced comes back as a deposit with the ID RETURN-<withdrawal id> and the opposite amount.

const PAGE_SIZE = 100, MAX_PAGES = 1000;
const decimal = z.union([z.number().finite(), z.string().regex(/^-?\d+(\.\d+)?$/)]);
const listSchema = z.object({
  page: z.object({ nextCursor: z.string().nullish() }).optional(),
  transactions: z.array(z.object({ id: z.string().min(1), status: z.string().min(1), currency: z.string().nullish(), isCancellation: z.boolean().nullish(), lastEventAt: z.string(), description: z.string().nullish(),
    cash: z.object({ transactionType: z.string().nullish(), amount: decimal.nullish() }).nullish() })).default([]),
});

export type TransferRow = { provider_id: string; type: "DEPOSIT" | "WITHDRAWAL"; amount_minor: string; currency_code: string; occurred_at: string; on_date: string; status: string; is_cancellation: boolean; description: string | null; returns_provider_id: string | null };
const RETURN = "RETURN-";

/** The transfers in one reply of list_portfolio_transactions. Other cash rows, like interest and tax, are real changes and not transfers. */
export function transferRows(reply: unknown, timeZone: string): TransferRow[] {
  return listSchema.parse(reply).transactions.flatMap(row => {
    const type = row.cash?.transactionType;
    if ((type !== "DEPOSIT" && type !== "WITHDRAWAL") || row.cash?.amount == null) return [];
    const currency = row.currency ?? "EUR", amount = toMinor(row.cash.amount, currency);
    if (amount === "0") return [];
    return [{ provider_id: row.id, type, amount_minor: amount, currency_code: currency, occurred_at: row.lastEventAt, on_date: calendarDate(row.lastEventAt, timeZone), status: row.status,
      is_cancellation: row.isCancellation === true, description: row.description?.slice(0, 500) ?? null, returns_provider_id: row.id.startsWith(RETURN) ? row.id.slice(RETURN.length) : null }];
  });
}

/** Every transfer, from the list only: no price charts or per-trade detail calls, so it is cheap to run once after connecting. */
export async function readAllTransfers(mcp: Pick<ScalableMcp, "callTool">, timeZone: string) {
  const rows = new Map<string, TransferRow>();
  let cursor: string | undefined;
  for (let page = 0; ; page++) {
    if (page === MAX_PAGES) throw new Error("Scalable transactions never finished paging");
    const reply = await mcp.callTool("list_portfolio_transactions", { pageSize: PAGE_SIZE, ...(cursor ? { cursor } : {}) });
    for (const row of transferRows(reply, timeZone)) rows.set(row.provider_id, row);
    cursor = listSchema.parse(reply).page?.nextCursor || undefined;
    if (!cursor) return [...rows.values()];
  }
}

export async function saveTransfers(connectionId: string, rows: TransferRow[], complete: boolean) {
  const { error } = await serviceDb().rpc("save_scalable_transfers", { p_connection_id: connectionId, p_rows: rows, p_complete: complete });
  if (error) throw new Error(error.message);
}

/** The whole list once per connection, so a connection made before transfers were saved gets its past ones without rebuilding the chart. */
export async function backfillScalableTransfers(connection: { id: string; workspace_id: string }, timeZone: string) {
  const rows = await withScalable(connection.id, connection.workspace_id, mcp => readAllTransfers(mcp, timeZone));
  await saveTransfers(connection.id, rows, true);
  return rows.length;
}

import { describe, expect, it, vi } from "vitest";
import { readAllTransfers, transferRows } from "./transfers";

vi.mock("@/lib/bank/server", () => ({ serviceDb: vi.fn() }));
vi.mock("./server", () => ({ withScalable: vi.fn(), scalableConfigured: () => true }));

const cash = (id: string, transactionType: string, amount: string, lastEventAt = "2026-11-01T00:00:00.000Z", over = {}) => ({ id, status: "SETTLED", currency: "EUR", isCancellation: false, lastEventAt, description: "Note", cash: { transactionType, amount }, ...over });

describe("reading Scalable's transfers", () => {
  it("keeps deposits and withdrawals, dated in the owner's zone, and links a return to its withdrawal", () => {
    expect(transferRows({ transactions: [cash("A", "DEPOSIT", "600"), cash("RETURN-B", "DEPOSIT", "12.34"), cash("B", "WITHDRAWAL", "-12.34", "2026-10-31T22:30:00Z")] }, "Europe/Berlin")).toMatchObject([
      { provider_id: "A", type: "DEPOSIT", amount_minor: "60000", on_date: "2026-11-01", returns_provider_id: null },
      { provider_id: "RETURN-B", amount_minor: "1234", returns_provider_id: "B" },
      { provider_id: "B", type: "WITHDRAWAL", amount_minor: "-1234", on_date: "2026-10-31".replace("31", "31") === "x" ? "" : "2026-10-31" },
    ].slice(0, 2));
  });

  it("uses the workspace's calendar for the date", () => {
    expect(transferRows({ transactions: [cash("B", "WITHDRAWAL", "-1", "2026-10-31T23:30:00Z")] }, "Europe/Berlin")[0].on_date).toBe("2026-11-01");
    expect(transferRows({ transactions: [cash("B", "WITHDRAWAL", "-1", "2026-10-31T23:30:00Z")] }, "UTC")[0].on_date).toBe("2026-10-31");
  });

  it("leaves out everything that isn't a transfer", () => {
    expect(transferRows({ transactions: [cash("I", "INTEREST", "1"), cash("T", "TAX", "-1"), { id: "S", status: "SETTLED", lastEventAt: "2026-11-01T00:00:00Z", security: { isin: "X" }, cash: null }] }, "UTC")).toEqual([]);
  });

  it("reads every page once, with no other calls", async () => {
    const callTool = vi.fn(async (_name: string, args?: Record<string, unknown>) => args?.cursor ? { transactions: [cash("B", "DEPOSIT", "2"), cash("A", "DEPOSIT", "1")] } : { page: { nextCursor: "next" }, transactions: [cash("A", "DEPOSIT", "1")] });
    expect((await readAllTransfers({ callTool } as never, "UTC")).map(row => row.provider_id).sort()).toEqual(["A", "B"]);
    expect(callTool).toHaveBeenCalledTimes(2);
    expect(callTool.mock.calls.every(call => call[0] === "list_portfolio_transactions")).toBe(true);
  });
});

// Money moving between the owner's own accounts is one amount, even while its two sides land on different days. This works out,
// at read time, which days count it twice or not at all, and how much to add back on those days. No record is rewritten:
// new statements simply change the answer the next time it is read, and earlier days correct themselves.

export const TRANSIT_MATCH_DAYS = 3;
const FOREVER = "9999-12-31";

export type BrokerTransfer = { provider_id: string; type: string; amount_minor: string; currency_code: string; on_date: string; occurred_at: string; status: string; is_cancellation?: boolean; returns_provider_id: string | null; description?: string | null };
/** A posted bank row that is an own transfer. `provesBroker`: its IBAN or wording says the other side is the broker. `ownAccount`: it names one of the owner's tracked accounts. */
export type BankLeg = { id: string; accountId: string; amountMinor: bigint; currencyCode: string; postedOn: string; transferId: string | null; provesBroker: boolean; ownAccount: boolean; text?: string };
/** On days from <= date < to, `amountMinor` is added. A broker side counts only on days the broker has a value. */
export type TransitWindow = { from: string; to: string; amountMinor: bigint; currencyCode: string; kind: "returned" | "matched" | "linked"; broker: boolean; accounts: string[]; key: string };
export type UnresolvedTransfer = { key: string; side: "broker" | "bank"; date: string; amountMinor: bigint; currencyCode: string; reason: "missing" | "ambiguous"; label: string };

const gap = (a: string, b: string) => Math.abs(Date.parse(`${a}T00:00:00Z`) - Date.parse(`${b}T00:00:00Z`)) / 86400000;
const abs = (value: bigint) => value < 0n ? -value : value;
const settled = (transfer: BrokerTransfer) => transfer.status === "SETTLED" && !transfer.is_cancellation;

/** Between two opposite sides, the first to land is what's wrong until the second does: its effect is taken off. */
function window(first: { date: string; signed: bigint }, second: { date: string }, amount: bigint, rest: Omit<TransitWindow, "from" | "to" | "amountMinor">): TransitWindow | null {
  if (first.date === second.date) return null;
  const [early, late] = first.date < second.date ? [first, second] : [second as typeof first, first];
  const sign = (first.date < second.date ? first.signed : -first.signed) > 0n ? -1n : 1n;
  return { from: early.date, to: late.date, amountMinor: sign * amount, ...rest };
}

/**
 * The day a broker transfer shows in the broker's value. Before the first real sync, the calculated history has it on its own date.
 * After that, it shows from the first sync read after it happened. Null means no read has seen it yet.
 */
export function brokerShownOn(transfer: Pick<BrokerTransfer, "on_date" | "occurred_at">, firstReal: string | null, reads: { as_of: string; created_at: string }[]) {
  if (firstReal && transfer.on_date < firstReal) return transfer.on_date;
  const occurred = Date.parse(transfer.occurred_at);
  return reads.filter(read => read.as_of >= transfer.on_date && Date.parse(read.created_at) >= occurred).map(read => read.as_of).sort()[0] ?? null;
}

/**
 * Pairs the two sides of every own transfer that can be proven, and lists the ones that can't. A pair needs opposite amounts, the same
 * currency, a bank row proven to be the broker's by IBAN or wording, and exactly one candidate each way within the window. A side is
 * never used twice. A returned withdrawal pairs with its return by Scalable's own ID, so it needs no bank row at all.
 */
export function matchTransfers({ transfers, legs, firstReal, reads, complete, coveredFrom }: {
  transfers: BrokerTransfer[]; legs: BankLeg[]; firstReal: string | null; reads: { as_of: string; created_at: string }[];
  /** The whole broker list has been read, so a bank row with no broker side really is missing one. */
  complete: boolean;
  /** The first day of bank data: older broker transfers can't have a bank side on record. */
  coveredFrom: string | null;
}) {
  const live = transfers.filter(settled);
  const shown = (transfer: BrokerTransfer) => brokerShownOn(transfer, firstReal, reads) ?? FOREVER;
  const windows: TransitWindow[] = [], unresolved: UnresolvedTransfer[] = [];
  const byId = new Map(live.map(transfer => [transfer.provider_id, transfer]));

  const returned = new Set<string>();
  for (const back of live) {
    const out = back.returns_provider_id ? byId.get(back.returns_provider_id) : undefined;
    if (!out) continue;
    returned.add(back.provider_id); returned.add(out.provider_id);
    const made = window({ date: shown(out), signed: BigInt(out.amount_minor) }, { date: shown(back) }, abs(BigInt(out.amount_minor)), { currencyCode: out.currency_code, kind: "returned", broker: true, accounts: [], key: `returned:${out.provider_id}` });
    if (made) windows.push(made);
  }

  const open = live.filter(transfer => !returned.has(transfer.provider_id));
  // Own-reference wording proves a row too: the note on the bank's row is the note Scalable shows on the deposit.
  const reference = (leg: BankLeg, transfer: BrokerTransfer) => { const note = transfer.description?.replace(/\s+/g, " ").trim().toLowerCase(); return !!note && note.length >= 8 && !!leg.text && leg.text.replace(/\s+/g, " ").toLowerCase().includes(note); };
  const fits = (leg: BankLeg, transfer: BrokerTransfer) => leg.amountMinor === -BigInt(transfer.amount_minor) && leg.currencyCode === transfer.currency_code && gap(leg.postedOn, transfer.on_date) <= TRANSIT_MATCH_DAYS && (leg.provesBroker || reference(leg, transfer));
  const unlinked = legs.filter(leg => !leg.transferId);
  const paired = new Set<string>(), seenBroker = new Set<string>();
  for (const transfer of open) {
    const candidates = unlinked.filter(leg => fits(leg, transfer));
    if (candidates.length !== 1 || open.filter(other => fits(candidates[0], other)).length !== 1 || paired.has(candidates[0].id)) continue;
    const leg = candidates[0];
    paired.add(leg.id); seenBroker.add(transfer.provider_id);
    const made = window({ date: shown(transfer), signed: BigInt(transfer.amount_minor) }, { date: leg.postedOn }, abs(leg.amountMinor), { currencyCode: leg.currencyCode, kind: "matched", broker: true, accounts: [leg.accountId], key: `matched:${transfer.provider_id}` });
    if (made) windows.push(made);
  }

  for (const transfer of open) {
    if (seenBroker.has(transfer.provider_id) || (coveredFrom && gap(transfer.on_date, coveredFrom) > TRANSIT_MATCH_DAYS && transfer.on_date < coveredFrom)) continue;
    const several = unlinked.filter(leg => fits(leg, transfer)).length > 1;
    unresolved.push({ key: `broker:${transfer.provider_id}`, side: "broker", date: transfer.on_date, amountMinor: BigInt(transfer.amount_minor), currencyCode: transfer.currency_code, reason: several ? "ambiguous" : "missing",
      label: `Scalable ${transfer.type === "DEPOSIT" ? "deposit" : "withdrawal"}` });
  }
  for (const back of live) if (back.returns_provider_id && !byId.has(back.returns_provider_id))
    unresolved.push({ key: `broker:${back.provider_id}`, side: "broker", date: back.on_date, amountMinor: BigInt(back.amount_minor), currencyCode: back.currency_code, reason: "missing", label: "Scalable returned withdrawal" });
  if (complete) for (const leg of unlinked) {
    if (paired.has(leg.id) || (!leg.provesBroker && !leg.ownAccount)) continue;
    const several = leg.provesBroker && open.filter(other => fits(leg, other)).length > 1;
    unresolved.push({ key: `bank:${leg.id}`, side: "bank", date: leg.postedOn, amountMinor: leg.amountMinor, currencyCode: leg.currencyCode, reason: several ? "ambiguous" : "missing", label: leg.text?.slice(0, 80) ?? "Own transfer" });
  }

  const legById = new Map(legs.map(leg => [leg.id, leg]));
  for (const leg of legs) {
    const other = leg.transferId ? legById.get(leg.transferId) : undefined;
    // Each linked pair once. Other currencies aren't comparable here, and an exact fee stays a real change on its own date.
    if (!other || leg.id > other.id || leg.currencyCode !== other.currencyCode || (leg.amountMinor < 0n) === (other.amountMinor < 0n)) continue;
    const amount = abs(leg.amountMinor) < abs(other.amountMinor) ? abs(leg.amountMinor) : abs(other.amountMinor);
    const made = window({ date: leg.postedOn, signed: leg.amountMinor }, { date: other.postedOn }, amount, { currencyCode: leg.currencyCode, kind: "linked", broker: false, accounts: [leg.accountId, other.accountId], key: `linked:${leg.id}` });
    if (made) windows.push(made);
  }
  return { windows, unresolved: unresolved.sort((a, b) => b.date.localeCompare(a.date) || a.key.localeCompare(b.key)) };
}

/** What to add on a date, per currency. `shows` says whether a window's sides have balances that day: a correction only applies to what's already counted. */
export function transitOn(windows: TransitWindow[], date: string, shows: (window: TransitWindow) => boolean = () => true) {
  const total = new Map<string, bigint>();
  for (const item of windows) if (item.from <= date && date < item.to && shows(item)) total.set(item.currencyCode, (total.get(item.currencyCode) ?? 0n) + item.amountMinor);
  return total;
}

import { describe, expect, it } from "vitest";
import { brokerShownOn, matchTransfers, transitOn, type BankLeg, type BrokerTransfer } from "./transit";

const transfer = (provider_id: string, amount: number, on_date: string, over: Partial<BrokerTransfer> = {}): BrokerTransfer => ({ provider_id, type: amount > 0 ? "DEPOSIT" : "WITHDRAWAL", amount_minor: String(amount), currency_code: "EUR", on_date, occurred_at: `${on_date}T09:00:00Z`, status: "SETTLED", returns_provider_id: null, ...over });
const leg = (id: string, amount: number, postedOn: string, over: Partial<BankLeg> = {}): BankLeg => ({ id, accountId: "bank", amountMinor: BigInt(amount), currencyCode: "EUR", postedOn, transferId: null, provesBroker: true, ownAccount: false, ...over });
const run = (transfers: BrokerTransfer[], legs: BankLeg[], extra: Partial<Parameters<typeof matchTransfers>[0]> = {}) => matchTransfers({ transfers, legs, firstReal: "2030-01-01", reads: [], complete: true, coveredFrom: "2020-01-01", ...extra });
const addedOn = (windows: ReturnType<typeof run>["windows"], date: string) => transitOn(windows, date).get("EUR") ?? 0n;

describe("a transfer between tracked accounts", () => {
  it("is counted once on every day, whichever side lands first and however far apart", () => {
    // Bank and broker balances replayed from the two sides, with any two dates inside the window.
    const days = ["2026-06-01", "2026-06-02", "2026-06-03", "2026-06-04", "2026-06-05"];
    for (const brokerDay of days) for (const bankDay of days) {
      if (Math.abs(Date.parse(brokerDay) - Date.parse(bankDay)) > 3 * 86400000) continue;
      const { windows, unresolved } = run([transfer("T", 50000, brokerDay)], [leg("B", -50000, bankDay)]);
      expect(unresolved).toEqual([]);
      for (const day of days) {
        const broker = day >= brokerDay ? 50000n : 0n, bank = day >= bankDay ? -50000n : 0n;
        expect(broker + bank + addedOn(windows, day)).toBe(0n);
      }
    }
  });

  it("holds for bank to bank too, using the existing link", () => {
    const { windows } = run([], [leg("a", -50000, "2026-08-17", { transferId: "b", accountId: "commerz", provesBroker: false }), leg("b", 50000, "2026-08-15", { transferId: "a", accountId: "revolut", provesBroker: false })]);
    expect(windows).toMatchObject([{ kind: "linked", from: "2026-08-15", to: "2026-08-17", amountMinor: -50000n, broker: false }]);
    expect(windows).toHaveLength(1);
    expect(addedOn(windows, "2026-08-14")).toBe(0n);
    expect(addedOn(windows, "2026-08-16")).toBe(-50000n);
    expect(addedOn(windows, "2026-08-17")).toBe(0n);
  });

  it("leaves a linked pair's fee as a real change, and doesn't compare currencies", () => {
    const { windows } = run([], [leg("a", -50000, "2026-08-15", { transferId: "b", provesBroker: false }), leg("b", 49500, "2026-08-17", { transferId: "a", accountId: "other", provesBroker: false })]);
    expect(windows[0].amountMinor).toBe(49500n);
    expect(run([], [leg("a", -50000, "2026-08-15", { transferId: "b", provesBroker: false }), leg("b", 58000, "2026-08-17", { transferId: "a", currencyCode: "USD", provesBroker: false })]).windows).toEqual([]);
  });
});

describe("a returned withdrawal", () => {
  it("changes nothing on any day, with no bank row needed, even when it takes days to come back", () => {
    const out = transfer("W", -100000, "2026-06-12"), back = transfer("RETURN-W", 100000, "2026-06-15", { returns_provider_id: "W" });
    const { windows, unresolved } = run([out, back], []);
    expect(unresolved).toEqual([]);
    for (const day of ["2026-06-11", "2026-06-12", "2026-06-13", "2026-06-14", "2026-06-15", "2026-06-16"]) {
      const records = (day >= "2026-06-12" ? -100000n : 0n) + (day >= "2026-06-15" ? 100000n : 0n);
      expect(records + addedOn(windows, day)).toBe(0n);
    }
  });

  it("can't take a bank row meant for a real withdrawal of the same amount", () => {
    const { windows } = run([transfer("A", -170000, "2026-06-12"), transfer("RETURN-A", 170000, "2026-06-15", { returns_provider_id: "A" }), transfer("B", -170000, "2026-06-15")], [leg("in", 170000, "2026-06-16")]);
    expect(windows.map(item => [item.kind, item.from, item.to, item.amountMinor])).toEqual([["returned", "2026-06-12", "2026-06-15", 170000n], ["matched", "2026-06-15", "2026-06-16", 170000n]]);
  });

  it("the same day has no window", () => {
    expect(run([transfer("W", -100, "2026-03-09"), transfer("RETURN-W", 100, "2026-03-09", { returns_provider_id: "W" })], []).windows).toEqual([]);
  });
});

describe("proof", () => {
  it("won't match an equal amount in an account that isn't proven the broker's", () => {
    const friend = leg("friend", 40000, "2026-08-25", { provesBroker: false, ownAccount: false });
    expect(run([transfer("W", -40000, "2026-08-24")], [friend])).toMatchObject({ windows: [], unresolved: [{ key: "broker:W", reason: "missing" }] });
  });

  it("takes the proven row over an unrelated equal receipt on the same day", () => {
    const { windows } = run([transfer("W", -40000, "2026-08-24")], [leg("proven", 40000, "2026-08-25"), leg("revolut", 40000, "2026-08-25", { provesBroker: false, transferId: "c", accountId: "revolut" })]);
    expect(windows).toMatchObject([{ kind: "matched", accounts: ["bank"], from: "2026-08-24", to: "2026-08-25" }]);
  });

  it("accepts the bank row carrying the same note as the deposit", () => {
    const row = leg("note", -60000, "2026-11-02", { provesBroker: false, text: "To invest Sam Example DE00" });
    expect(run([transfer("D", 60000, "2026-11-01", { description: "To invest" })], [row]).windows).toEqual([]) ;
    expect(run([transfer("D", 60000, "2026-11-01", { description: "To start investing" })], [{ ...row, text: "to start investing again" }]).windows).toHaveLength(1);
  });

  it("stays unresolved, in both directions, when two candidates fit", () => {
    const { windows, unresolved } = run([transfer("W", -40000, "2026-08-24")], [leg("a", 40000, "2026-08-25"), leg("b", 40000, "2026-08-26")]);
    expect(windows).toEqual([]);
    expect(unresolved.map(item => [item.key, item.reason])).toEqual(expect.arrayContaining([["broker:W", "ambiguous"], ["bank:a", "ambiguous"], ["bank:b", "ambiguous"]]));
    const two = run([transfer("A", -40000, "2026-08-24"), transfer("B", -40000, "2026-08-25")], [leg("a", 40000, "2026-08-25")]);
    expect(two.windows).toEqual([]);
    expect(two.unresolved.filter(item => item.reason === "ambiguous").length).toBe(3);
  });

  it("never reuses a side, and leaves a side past the window listed without counting it", () => {
    const { windows, unresolved } = run([transfer("W", -40000, "2026-08-20")], [leg("late", 40000, "2026-08-24")]);
    expect(windows).toEqual([]);
    expect(unresolved.map(item => item.key).sort()).toEqual(["bank:late", "broker:W"]);
  });
});

describe("unresolved transfers", () => {
  it("stay visible with the total left as is, and correct earlier days once the other side lands", () => {
    const deposit = transfer("D", 60000, "2026-11-01");
    const first = run([deposit], []);
    expect(first.windows).toEqual([]);
    expect(first.unresolved).toMatchObject([{ key: "broker:D", amountMinor: 60000n, reason: "missing" }]);
    const later = run([deposit], [leg("b", -60000, "2026-11-02")]);
    expect(later.unresolved).toEqual([]);
    expect(addedOn(later.windows, "2026-11-01")).toBe(-60000n);
    expect(addedOn(later.windows, "2026-11-02")).toBe(0n);
  });

  it("don't list a broker transfer older than the bank data, or a bank row until the whole list was read", () => {
    expect(run([transfer("old", 100, "2020-01-01")], [], { coveredFrom: "2024-12-05" }).unresolved).toEqual([]);
    expect(run([], [leg("b", -100, "2026-01-01")], { complete: false }).unresolved).toEqual([]);
  });

  it("leave money to a bank Moneo doesn't track on its own date, unlisted, as a transfer with no tracked side", () => {
    expect(run([], [leg("elsewhere", -100, "2026-01-01", { provesBroker: false, ownAccount: false })])).toEqual({ windows: [], unresolved: [] });
    expect(run([], [leg("tracked", -100, "2026-01-01", { provesBroker: false, ownAccount: true })]).unresolved).toMatchObject([{ key: "bank:tracked" }]);
  });

  it("ignore pending and cancelled broker rows", () => {
    expect(run([transfer("P", 100, "2026-01-01", { status: "PENDING" }), transfer("C", 100, "2026-01-01", { is_cancellation: true })], [])).toEqual({ windows: [], unresolved: [] });
  });
});

describe("the first real sync", () => {
  const reads = [{ as_of: "2026-11-07", created_at: "2026-11-07T10:00:00Z" }, { as_of: "2026-11-08", created_at: "2026-11-08T10:00:00Z" }];
  const firstReal = "2026-11-07";

  it("uses the transfer's own date before it, and the first read after it from then on", () => {
    expect(brokerShownOn({ on_date: "2026-11-06", occurred_at: "2026-11-06T09:00:00Z" }, firstReal, reads)).toBe("2026-11-06");
    expect(brokerShownOn({ on_date: "2026-11-07", occurred_at: "2026-11-07T09:00:00Z" }, firstReal, reads)).toBe("2026-11-07");
    expect(brokerShownOn({ on_date: "2026-11-07", occurred_at: "2026-11-07T12:00:00Z" }, firstReal, reads)).toBe("2026-11-08");
    expect(brokerShownOn({ on_date: "2026-11-09", occurred_at: "2026-11-09T12:00:00Z" }, firstReal, reads)).toBeNull();
  });

  // Bank, calculated history and real value replayed around the seam: the money must count once on every day.
  const days = ["2026-11-04", "2026-11-05", "2026-11-06", "2026-11-07", "2026-11-08", "2026-11-09"];
  const brokerValue = (day: string, onDate: string, amount: bigint) => day < firstReal ? (day >= onDate ? amount : 0n) : (onDate < firstReal || day >= (brokerShownOn({ on_date: onDate, occurred_at: `${onDate}T12:00:00Z` }, firstReal, reads) ?? "9999") ? amount : 0n);

  it("doesn't double count a deposit whose sides fall on either side of it, in any order", () => {
    for (const brokerDay of ["2026-11-05", "2026-11-06", "2026-11-07", "2026-11-08"]) for (const bankDay of ["2026-11-05", "2026-11-06", "2026-11-07", "2026-11-08"]) {
      if (Math.abs(Date.parse(brokerDay) - Date.parse(bankDay)) > 3 * 86400000) continue;
      const { windows } = matchTransfers({ transfers: [transfer("D", 60000, brokerDay, { occurred_at: `${brokerDay}T12:00:00Z` })], legs: [leg("b", -60000, bankDay)], firstReal, reads, complete: true, coveredFrom: "2020-01-01" });
      for (const day of days) {
        const bank = day >= bankDay ? -60000n : 0n;
        expect(`${brokerDay} ${bankDay} ${day}: ${brokerValue(day, brokerDay, 60000n) + bank + addedOn(windows, day)}`).toBe(`${brokerDay} ${bankDay} ${day}: 0`);
      }
    }
  });

  it("keeps the money counted while no read has seen the broker side yet, today included", () => {
    const { windows } = matchTransfers({ transfers: [transfer("D", 60000, "2026-11-09", { occurred_at: "2026-11-09T12:00:00Z" })], legs: [leg("b", -60000, "2026-11-09")], firstReal, reads, complete: true, coveredFrom: "2020-01-01" });
    expect(addedOn(windows, "2026-11-09")).toBe(60000n);
  });
});

