type Row = Record<string, unknown>;
const read = (name: string): Row[] => JSON.parse(readFileSync(`${DUMP}/${name}.json`, "utf8"));
const tables: Record<string, Row[]> = {};
for (const name of ["accounts", "balance_snapshots", "transactions", "transaction_link_fees", "pending_hold_resolutions", "wealth_items", "wealth_events", "scalable_value_history", "scalable_connections", "own_account_identifiers", "bank_connection_accounts", "imports"]) tables[name] = read(name);
