function from(name: string) {
  const filters: ((row: Row) => boolean)[] = [];
  let slice: [number, number] | null = null, cap: number | null = null;
  const rows = () => { let out = (tables[name] ?? []).filter(row => filters.every(test => test(row))); if (slice) out = out.slice(slice[0], slice[1] + 1); if (cap !== null) out = out.slice(0, cap); return out; };
  const query: Record<string, unknown> = {
    select: () => query, order: () => query,
    eq: (column: string, value: unknown) => { filters.push(row => row[column] === value); return query; },
    neq: (column: string, value: unknown) => { filters.push(row => row[column] !== value); return query; },
    is: (column: string, value: unknown) => { filters.push(row => (row[column] ?? null) === value); return query; },
    not: (column: string, _op: string, value: unknown) => { filters.push(row => (row[column] ?? null) !== value); return query; },
    in: (column: string, values: unknown[]) => { filters.push(row => values.includes(row[column])); return query; },
    gte: () => query,
    limit: (count: number) => { cap = count; return query; },
    range: (start: number, end: number) => { slice = [start, end]; return query; },
    maybeSingle: async () => ({ data: rows()[0] ?? null, error: null }),
    single: async () => ({ data: rows()[0] ?? null, error: null }),
    then: (done: (value: unknown) => unknown) => Promise.resolve({ data: rows(), error: null }).then(done),
  };
  return query;
}
