// Upgrade rehearsal on the private stack only: applies migrations up to the owner's current head, seeds made-up rows shaped like
// a real workspace, applies the new migrations, and checks nothing was lost.
import { createRequire } from "node:module";
import { readFileSync, readdirSync } from "node:fs";
const require = createRequire(process.cwd() + "/package.json");
const postgres = require("postgres");
const env = Object.fromEntries(readFileSync(".env", "utf8").split(/\r?\n/).filter(line => line.includes("=") && !line.startsWith("#")).map(line => [line.slice(0, line.indexOf("=")), line.slice(line.indexOf("=") + 1)]));
if (!env.SUPABASE_DB_URL.includes(":54722/")) throw new Error("Not the private stack");
const HEAD = "202611080002";
const db = postgres(env.SUPABASE_DB_URL, { max: 1, onnotice: () => {} });
await db`create schema if not exists supabase_migrations`;
await db`create table if not exists supabase_migrations.schema_migrations (version text primary key, statements text[], name text)`;
const applied = new Set((await db`select version from supabase_migrations.schema_migrations`).map(row => row.version));
if (applied.size) throw new Error("Expected an empty database");
const files = readdirSync("supabase/migrations").filter(file => file.endsWith(".sql")).sort();
const apply = async file => { const source = readFileSync(`supabase/migrations/${file}`, "utf8"), version = file.split("_")[0]; await db.begin(async tx => { await tx.unsafe(source); await tx`insert into supabase_migrations.schema_migrations (version, name, statements) values (${version}, ${file.slice(version.length + 1, -4)}, ${[source]})`; }); };
for (const file of files.filter(file => file.split("_")[0] <= HEAD)) await apply(file);
const actor = crypto.randomUUID();
await db`insert into auth.users(id,email) values(${actor},${`qa-${actor}@example.invalid`})`;
const [{ id: ws }] = await db`select id from public.workspaces where owner_id=${actor}`;
const account = crypto.randomUUID(), bank = crypto.randomUUID(), scalable = crypto.randomUUID(), item = crypto.randomUUID();
await db`insert into public.accounts(id,workspace_id,name,currency_code) values(${account},${ws},'Upgrade bank','EUR')`;
await db`insert into public.balance_snapshots(workspace_id,account_id,amount_minor,currency_code,as_of,provenance,boundary_kind) values(${ws},${account},109,'EUR','2026-10-30T23:00:00Z','import:a:row:1','date_only'),(${ws},${account},109,'EUR','2026-10-30T23:00:00Z','import:b:row:9','date_only')`;
await db`insert into public.bank_connections(id,workspace_id,aspsp_name,aspsp_country,status,session_id_encrypted,valid_until,last_synced_at) values(${bank},${ws},'Upgrade bank','DE','active','sealed',now()+interval '30 days','2026-11-08T10:00:00Z')`;
await db`insert into public.scalable_connections(id,workspace_id,client_id,redirect_uri,status,tokens_encrypted,portfolio,last_synced_at,history_status,history_checked_on) values(${scalable},${ws},'client','http://localhost/callback','active','sealed',${db.json({ totalMinor: "100", itemIds: [item], currency: "EUR" })},'2026-11-08T10:00:00Z','ok','2026-11-08')`;
await db`insert into public.wealth_items(id,workspace_id,kind,name,currency_code,amount_minor,as_of) values(${item},${ws},'asset','Scalable cash','EUR',100,'2026-11-08')`;
await db`insert into public.scalable_value_history(workspace_id,on_date,currency_code,securities_minor,crypto_minor,cash_minor,total_minor) select ${ws},d::date,'EUR',1,2,3,6 from generate_series('2025-02-03'::date,('2025-02-03'::date + 641),interval '1 day') d`;
const before = await db`select (select count(*)::int from public.scalable_value_history) history,(select count(*)::int from public.balance_snapshots) balances,(select count(*)::int from public.wealth_items) items,(select portfolio::text from public.scalable_connections limit 1) portfolio`;
for (const file of files.filter(file => file.split("_")[0] > HEAD)) { await apply(file); console.log("applied", file); }
const after = await db`select (select count(*)::int from public.scalable_value_history) history,(select count(*)::int from public.balance_snapshots) balances,(select count(*)::int from public.wealth_items) items,(select portfolio::text from public.scalable_connections limit 1) portfolio`;
